tasks.answer:
input_num = [10, 5, 3, 13, 2, 14, 7, 9, 4, 12]
bst = [0] * 30

def insert(idx, num):
    if bst[idx] == 0:
        bst[idx] = num
    elif num < bst[idx]:
        insert(idx * 2, num)
    else:
        insert(idx * 2 + 1, num)

for v in input_num:
    insert(1, v)

def count(num):
    idx, cnt = 1, 1
    while bst[idx] != num:
        if num < bst[idx]:
            idx = idx * 2
        else:
            idx = idx * 2 + 1
        cnt += 1
    return cnt

for x in [5, 2, 7, 12]:
    print(f'{x}: 트리 {count(x)}회, 처음부터 {input_num.index(x) + 1}회')
